// ARKHE-N v2.1 Witness Preprocessor
const event = $input.first().json;
const timestamp = Date.now();
const agent_id = event.agent_id || event.id || 'unknown';
const agent_type = event.agent_type || 'specialist';
const anchor_type = event.anchor_type || 'unknown';
const curvature = parseFloat(event.curvature) || 0.0;
const topological_sector = event.topological_sector || 'VortexBound';
const reliability = parseFloat(event.reliability) || 0.5;
const audit_count = parseInt(event.audit_count) || 0;
const correction_count = parseInt(event.correction_count) || 0;
const entanglement_entropy = parseFloat(event.entanglement_entropy) || 0.0;
const collapse_probability = parseFloat(event.collapse_probability) || 0.0;
const pq_scheme = event.pq_scheme || 'Falcon512';
const signature = event.signature || '';
const lat = parseFloat(event.lat) || 0.0;
const lon = parseFloat(event.lon) || 0.0;
// Simple hash using n8n-compatible approach
const hashInput = JSON.stringify(event) + timestamp;
let hash = 0;
for (let i = 0; i < hashInput.length; i++) {
  const char = hashInput.charCodeAt(i);
  hash = ((hash << 5) - hash) + char;
  hash = hash & hash;
}
const event_hash = '0x' + Math.abs(hash).toString(16).padStart(64, '0');
return [{
  json: {
    ...event,
    event_hash,
    timestamp,
    agent_id,
    agent_type,
    anchor_type,
    curvature,
    topological_sector,
    reliability,
    audit_count,
    correction_count,
    entanglement_entropy,
    collapse_probability,
    pq_scheme,
    signature,
    lat,
    lon,
    witness_status: 'pending'
  }
}];

// ARKHE-N v2.1 Witness Processor
const response = $input.first().json;
const event = $input.first().json;
if (response.is_anchored === true) {
  event.witness_status = 'ANCHORED';
  event.block_height = response.block_height || 0;
  event.energy_cost_mj = response.energy_cost_mj || 0;
  event.anchor_type = response.anchor_type || event.anchor_type;
  event.curvature = parseFloat(response.curvature) || event.curvature;
  event.topological_sector = response.topological_sector || event.topological_sector;
  event.reliability = parseFloat(response.reliability) || event.reliability;
  event.audit_count = (parseInt(event.audit_count) || 0) + 1;
  event.correction_count = parseInt(response.correction_count) || event.correction_count;
  event.pq_scheme = response.pq_scheme || event.pq_scheme;
  event.signature = response.signature || event.signature;
  event.chord_latency_ms = parseFloat(response.chord_latency_ms) || 3.3;
} else {
  event.witness_status = 'REJECTED';
  event.rejection_reason = response.rejection_reason || 'unknown';
}
return [{ json: event }];
